221	        .frame(maxWidth: .infinity)
222	    }
223	
224	    private var swipe: some Gesture {
225	        DragGesture(minimumDistance: 12)
226	            .onChanged { v in if v.translation.width < 0 { dragOffset = max(-revealWidth, v.translation.width) } }
227	            .onEnded { v in withAnimation(.snappy) { dragOffset = v.translation.width < -40 ? -revealWidth : 0 } }
228	    }
229	}
