//
//  ActiveWorkoutView.swift
//  Replog
//
//  The core logging loop: running timer, optional in-header rest timer, set rows with
//  finance-style trend arrows, inline editors, swipe-to-delete, spring reorder of
//  finished exercises, and Finish.
//

import SwiftUI
import SwiftData

struct ActiveWorkoutView: View {
    @Environment(\.modelContext) private var context
    @Environment(\.dismiss) private var dismiss
    @Environment(\.exerciseCatalog) private var catalog
    @Query private var profiles: [UserProfile]
    @Query private var settingsList: [AppSettings]
    @Bindable var session: ActiveSession

    @State private var expandedSetID: UUID?
    @State private var restTimer = RestTimerModel()
    @State private var detailRef: ExerciseRef?
    @State private var showFinishConfirm = false
    @State private var showCelebration = false
    @State private var didCelebrate = false

    private var profile: UserProfile { profiles.first ?? context.userProfile() }
    private var settings: AppSettings { settingsList.first ?? context.appSettings() }

    var body: some View {
        VStack(spacing: 0) {
            header
            ScrollView {
                LazyVStack(spacing: 12) {
                    ForEach(session.orderedExercises) { exercise in
                        ExerciseLogCard(
                            exercise: exercise,
                            name: catalog.exercise(id: exercise.exId)?.name ?? exercise.exId,
                            muscle: catalog.exercise(id: exercise.exId)?.primaryMuscles.first?.displayName ?? "",
                            imageName: catalog.exercise(id: exercise.exId)?.imageResourceNames.first,
                            units: settings.units,
                            expandedSetID: $expandedSetID,
                            onCheck: { toggle($0, in: exercise) },
                            onInfo: { detailRef = ExerciseRef(id: exercise.exId) },
                            onAddSet: { addSet(to: exercise) },
                            onDeleteSet: { deleteSet($0, from: exercise) },
                            onChange: { try? context.save() }
                        )
                        .id(exercise.id)
                    }
                }
                .padding(16)
                .animation(.spring(response: 0.5, dampingFraction: 0.8), value: session.orderedExercises.map(\.id))
            }
            .scrollDismissesKeyboard(.immediately)
        }
        .hideKeyboardOnTap()
        .background(Color.bg.ignoresSafeArea())
        .sheet(item: $detailRef) { ref in
            NavigationStack { ExerciseDetailView(exId: ref.id, showProgress: true) }
        }
        .confirmationDialog("Finish workout?", isPresented: $showFinishConfirm, titleVisibility: .visible) {
            Button("Finish anyway", role: .destructive) { finish() }
            Button("Save for later") { close() }
            Button("Keep training", role: .cancel) {}
        } message: {
            Text(finishWarningMessage)
        }
        .overlay {
            if showCelebration {
                CelebrationOverlay(
                    sets: session.completedSets,
                    exercises: session.exercises.count,
                    onFinish: { showCelebration = false; finish() },
                    onKeepGoing: { withAnimation(.snappy) { showCelebration = false } }
                )
                .transition(.opacity)
            }
        }
        // Auto-celebrate the moment the final set is checked (Duolingo-style).
        .onChange(of: session.isComplete) { _, complete in
            if complete && !didCelebrate {
                didCelebrate = true
                withAnimation(.snappy) { showCelebration = true }
            } else if !complete {
                didCelebrate = false
            }
        }
        .onAppear {
            // Handles resuming a session that is already fully complete.
            if session.isComplete && !didCelebrate {
                didCelebrate = true
                showCelebration = true
            }
        }
    }

    private var finishWarningMessage: String {
        let remaining = max(0, session.totalSets - session.completedSets)
        var msg = "You still have \(remaining) set\(remaining == 1 ? "" : "s") to go. "
        if profile.streak > 0 {
            msg += "Finishing now won't count this workout, and you'll lose your "
                + "\(profile.streak)-workout streak. "
        } else {
            msg += "Finishing now won't count this workout toward your streak. "
        }
        msg += "Save it for later to pick up where you left off."
        return msg
    }

    // MARK: Header

    private var header: some View {
        VStack(spacing: 10) {
            HStack {
                circleButton("xmark") { close() }
                Spacer()
                VStack(spacing: 1) {
                    Text(session.name).font(.rounded(16, .heavy)).foregroundStyle(Color.textPrimary)
                    TimelineView(.periodic(from: .now, by: 1)) { _ in
                        Text(elapsedText).font(.rounded(13, .bold)).foregroundStyle(Color.accent).tabularNumbers()
                    }
                }
                Spacer()
                circleButton("timer") { restTimer.start(seconds: settings.restSeconds) }
                Button { attemptFinish() } label: {
                    Text("Finish").font(.rounded(14, .heavy)).foregroundStyle(.white)
                        .padding(.horizontal, 14).padding(.vertical, 8)
                        .background(Capsule().fill(Color.accent))
                }
                .buttonStyle(.plain)
            }

            progressBar

            if restTimer.isRunning { restBar }
        }
        .padding(.horizontal, 16).padding(.top, 8).padding(.bottom, 12)
        .background(Color.surface.ignoresSafeArea(edges: .top))
    }

    private var progressBar: some View {
        VStack(spacing: 4) {
            GeometryReader { geo in
                ZStack(alignment: .leading) {
                    Capsule().fill(Color.surface2)
                    Capsule().fill(Color.accent)
                        .frame(width: geo.size.width * fractionComplete)
                }
            }
            .frame(height: 6)
            Text("\(session.completedSets) of \(session.totalSets) sets complete")
                .font(.rounded(11, .heavy)).foregroundStyle(Color.text3)
                .frame(maxWidth: .infinity, alignment: .leading)
        }
    }

    private var restBar: some View {
        TimelineView(.periodic(from: .now, by: 1)) { context in
            let remaining = restTimer.remaining(at: context.date)
            HStack(spacing: 12) {
                ZStack {
                    Circle().stroke(Color.accent.opacity(0.25), lineWidth: 3)
                    Circle().trim(from: 0, to: restTimer.fraction(at: context.date))
                        .stroke(Color.accent, style: StrokeStyle(lineWidth: 3, lineCap: .round))
                        .rotationEffect(.degrees(-90))
                }
                .frame(width: 26, height: 26)
                Text(timeString(remaining)).font(.rounded(15, .heavy)).foregroundStyle(Color.textPrimary).tabularNumbers()
                Spacer()
                restButton("−15") { restTimer.adjust(-15) }
                restButton("+15") { restTimer.adjust(15) }
                restButton("Skip") { restTimer.skip() }
            }
            .padding(.horizontal, 12).padding(.vertical, 8)
            .background(RoundedRectangle(cornerRadius: 12, style: .continuous).fill(Color.accentSoft))
            .onChange(of: remaining) { _, new in if new == 0 { restTimer.skip() } }
        }
    }

    private func circleButton(_ symbol: String, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            Image(systemName: symbol).font(.system(size: 14, weight: .heavy)).foregroundStyle(Color.text2)
                .frame(width: 38, height: 38)
                .glassEffect(.regular, in: .circle)
        }
        .buttonStyle(.plain)
    }

    private func restButton(_ label: String, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            Text(label).font(.rounded(12, .heavy)).foregroundStyle(Color.accent)
                .padding(.horizontal, 12).padding(.vertical, 7)
                .glassEffect(.regular.tint(Color.surface), in: .capsule)
        }
        .buttonStyle(.plain)
    }

    // MARK: Derived

    private var fractionComplete: CGFloat {
        session.totalSets == 0 ? 0 : CGFloat(session.completedSets) / CGFloat(session.totalSets)
    }

    private var elapsedText: String {
        timeString(Int(Date().timeIntervalSince(session.startedAt)))
    }

    private func timeString(_ seconds: Int) -> String {
        String(format: "%d:%02d", seconds / 60, seconds % 60)
    }

    // MARK: Actions

    private func toggle(_ set: LoggedSet, in exercise: SessionExercise) {
        set.done.toggle()
        let justCompleted = set.done
        // Maintain doneOrder so finished exercises sort to the bottom in completion order.
        if exercise.isDone {
            let maxOrder = session.exercises.map(\.doneOrder).max() ?? -1
            exercise.doneOrder = maxOrder + 1
        } else {
            exercise.doneOrder = -1
        }
        // (Re)start the rest timer on every set completion — when auto-start is on, or
        // whenever a timer is already running (so checking a set resets the active
        // countdown). Uses this exercise's own rest duration when set, else the app default.
        if justCompleted && (settings.restTimerAuto || restTimer.isRunning) {
            restTimer.start(seconds: exercise.restSeconds ?? settings.restSeconds)
        }
        try? context.save()
    }

    private func addSet(to exercise: SessionExercise) {
        let last = exercise.orderedSets.last
        let set = LoggedSet(weightKg: last?.weightKg ?? 20, reps: last?.reps ?? 10, rpe: last?.rpe ?? 8,
                            prevWeight: last?.prevWeight, prevReps: last?.prevReps, order: exercise.sets.count)
        set.exercise = exercise
        context.insert(set)
        try? context.save()
    }

    private func deleteSet(_ set: LoggedSet, from exercise: SessionExercise) {
        context.delete(set)
        try? context.save()
    }

    /// Closes the cover but keeps the session: it's paused & persisted, continuable from Today.
    private func close() {
        session.isOpen = false
        try? context.save()
        dismiss()
    }

    private func attemptFinish() {
        if session.isComplete {
            withAnimation(.snappy) { showCelebration = true }
        } else {
            showFinishConfirm = true
        }
    }

    private func finish() {
        SessionFinisher.finish(session, profile: profile, context: context)
        dismiss()
    }
}

//
//  Session.swift
//  Replog
//
//  Live workout logging models. An ActiveSession is created from a Workout's
//  prescribed sets and persisted so an in-progress workout survives relaunch.
//

import Foundation
import SwiftData

@Model
final class ActiveSession {
    var id: UUID = UUID()
    var workoutId: UUID?
    var name: String = ""
    var planName: String = ""
    var startedAt: Date = Date()
    /// Whether the live session is currently presented. Closing with "X" sets this
    /// false (paused & persisted) so the workout survives and can be continued; it is
    /// only deleted on Finish.
    var isOpen: Bool = true

    @Relationship(deleteRule: .cascade, inverse: \SessionExercise.session)
    var exercises: [SessionExercise] = []

    init(workoutId: UUID?, name: String, planName: String, startedAt: Date = Date()) {
        self.workoutId = workoutId
        self.name = name
        self.planName = planName
        self.startedAt = startedAt
    }

    /// Exercises ordered with finished ones (positive doneOrder) pushed to the bottom.
    var orderedExercises: [SessionExercise] {
        exercises.sorted { a, b in
            switch (a.isDone, b.isDone) {
            case (false, true): return true
            case (true, false): return false
            case (true, true):  return a.doneOrder < b.doneOrder
            case (false, false): return a.order < b.order
            }
        }
    }

    var totalSets: Int { exercises.reduce(0) { $0 + $1.sets.count } }
    var completedSets: Int { exercises.reduce(0) { $0 + $1.sets.filter(\.done).count } }
    var isComplete: Bool { totalSets > 0 && completedSets == totalSets }
}

@Model
final class SessionExercise {
    var id: UUID = UUID()
    var exId: String = ""
    var order: Int = 0
    /// Monotonic counter set when the exercise becomes fully done (drives reorder). -1 = not done.
    var doneOrder: Int = -1
    /// Rest between sets for this exercise, in seconds. `nil` = use the app default.
    /// Copied from the plan's `PlanItem.restSeconds` when the session is built.
    var restSeconds: Int?
    var session: ActiveSession?

    @Relationship(deleteRule: .cascade, inverse: \LoggedSet.exercise)
    var sets: [LoggedSet] = []

    init(exId: String, order: Int = 0) {
        self.exId = exId
        self.order = order
    }

    var orderedSets: [LoggedSet] { sets.sorted { $0.order < $1.order } }
    var isDone: Bool { !sets.isEmpty && sets.allSatisfy(\.done) }

    /// The heaviest set by estimated 1RM (used for history & "best").
    var topSet: LoggedSet? {
        sets.max { Formulas.e1rm(kg: $0.weightKg, reps: $0.reps) < Formulas.e1rm(kg: $1.weightKg, reps: $1.reps) }
    }
}

@Model
final class LoggedSet {
    var id: UUID = UUID()
    var weightKg: Double = 20
    var reps: Int = 10
    var rpe: Int = 8
    var done: Bool = false
    /// Same set index's weight/reps from the previous session (drives trend arrows).
    var prevWeight: Double?
    var prevReps: Int?
    var order: Int = 0
    var exercise: SessionExercise?

    init(weightKg: Double, reps: Int, rpe: Int, prevWeight: Double? = nil, prevReps: Int? = nil, order: Int = 0) {
        self.weightKg = weightKg
        self.reps = reps
        self.rpe = rpe
        self.prevWeight = prevWeight
        self.prevReps = prevReps
        self.order = order
    }

    var weightTrend: Trend { TrendCalculator.trend(current: weightKg, previous: prevWeight) }
    var repsTrend: Trend { TrendCalculator.trend(current: Double(reps), previous: prevReps.map(Double.init)) }
}

//
//  ReplogStore.swift
//  Replog
//
//  Central SwiftData schema, container factories, and fetch-or-create singletons
//  for UserProfile / AppSettings.
//

import Foundation
import SwiftData

enum ReplogSchema {
    /// All persisted model types.
    static let models: [any PersistentModel.Type] = [
        Plan.self, Workout.self, PlanItem.self, SetTemplate.self,
        ActiveSession.self, SessionExercise.self, LoggedSet.self,
        HistoryEntry.self, UserProfile.self, AppSettings.self,
        CoachingLog.self
    ]

    /// The app's on-disk container.
    /// On a fresh device install `Library/Application Support` may not exist yet, which
    /// makes SwiftData fail to create its store ("Failed to create file; code = 2"). We
    /// create that directory first, then open the store; if the store itself is corrupt
    /// or schema-incompatible (e.g. left over from an older build), we wipe it once and
    /// retry, falling back to in-memory as a last resort so the app always launches.
    @MainActor
    static func container() -> ModelContainer {
        let schema = Schema(models)
        let config = ModelConfiguration(isStoredInMemoryOnly: false)
        let storeURL = config.url

        // Ensure the store's parent directory exists.
        try? FileManager.default.createDirectory(
            at: storeURL.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )

        if let c = try? ModelContainer(for: schema, configurations: config) { return c }

        // Genuine corruption / incompatible schema: remove the store files and retry once.
        for suffix in ["", "-shm", "-wal"] {
            try? FileManager.default.removeItem(at: URL(fileURLWithPath: storeURL.path + suffix))
        }
        if let recovered = try? ModelContainer(for: schema, configurations: config) { return recovered }

        // Last resort so the UI still runs (data won't persist).
        return try! ModelContainer(for: schema, configurations: ModelConfiguration(isStoredInMemoryOnly: true))
    }

    /// An ephemeral container for tests and SwiftUI previews.
    @MainActor
    static func inMemoryContainer() -> ModelContainer {
        let config = ModelConfiguration(isStoredInMemoryOnly: true)
        // Force-try is acceptable here: an in-memory store cannot fail for schema reasons
        // that wouldn't also fail the on-disk store caught at app launch.
        return try! ModelContainer(for: Schema(models), configurations: config)
    }
}

// MARK: - Singleton fetch-or-create

extension ModelContext {
    /// Returns the single UserProfile, creating it on first access.
    func userProfile() -> UserProfile {
        if let existing = (try? fetch(FetchDescriptor<UserProfile>()))?.first {
            return existing
        }
        let profile = UserProfile()
        insert(profile)
        return profile
    }

    /// Returns the single AppSettings row, creating it on first access.
    func appSettings() -> AppSettings {
        if let existing = (try? fetch(FetchDescriptor<AppSettings>()))?.first {
            return existing
        }
        let settings = AppSettings()
        insert(settings)
        return settings
    }

    /// All plans in display order.
    func allPlans() -> [Plan] {
        let descriptor = FetchDescriptor<Plan>(sortBy: [SortDescriptor(\.order)])
        return (try? fetch(descriptor)) ?? []
    }

    /// Recomputes both streaks on `profile` from the current plan schedule + completed days.
    /// Call after finishing a workout or whenever the schedule changes.
    func recomputeStreaks(profile: UserProfile, today: Date = Date()) {
        let scheduled = StreakEngine.scheduledDays(in: allPlans())
        profile.streak = StreakEngine.workoutStreak(
            scheduledDays: scheduled, doneDates: profile.doneDates, today: today)
        profile.weekStreak = StreakEngine.weekStreak(
            scheduledDays: scheduled, doneDates: profile.doneDates, today: today)
    }

    /// History entries for one exercise, oldest first.
    func history(forExercise exId: String) -> [HistoryEntry] {
        let descriptor = FetchDescriptor<HistoryEntry>(
            predicate: #Predicate { $0.exId == exId },
            sortBy: [SortDescriptor(\.date)]
        )
        return (try? fetch(descriptor)) ?? []
    }

    // MARK: - Coaching memory

    /// Records a coaching note into the durable memory and returns the inserted log.
    /// This is the single write path the trainer uses to "remember" something.
    @discardableResult
    func recordCoaching(
        _ kind: CoachingKind,
        summary: String,
        date: Date = Date(),
        exId: String? = nil,
        planId: UUID? = nil,
        payload: CoachingPayload = CoachingPayload()
    ) -> CoachingLog {
        let log = CoachingLog(
            kind: kind, summary: summary, date: date,
            exId: exId, planId: planId, payload: payload
        )
        insert(log)
        return log
    }

    /// Coaching logs, newest first. Optionally filtered to one `kind` and capped to `limit`.
    func coachingLogs(kind: CoachingKind? = nil, limit: Int? = nil) -> [CoachingLog] {
        var descriptor = FetchDescriptor<CoachingLog>(sortBy: [SortDescriptor(\.date, order: .reverse)])
        if let kind {
            let raw = kind.rawValue
            descriptor.predicate = #Predicate { $0.kindRaw == raw }
        }
        if let limit { descriptor.fetchLimit = limit }
        return (try? fetch(descriptor)) ?? []
    }

    /// The most recent coaching log of a given kind, if any.
    func latestCoachingLog(kind: CoachingKind) -> CoachingLog? {
        coachingLogs(kind: kind, limit: 1).first
    }

    /// Coaching logs concerning one exercise, newest first.
    func coachingLogs(forExercise exId: String) -> [CoachingLog] {
        let descriptor = FetchDescriptor<CoachingLog>(
            predicate: #Predicate { $0.exId == exId },
            sortBy: [SortDescriptor(\.date, order: .reverse)]
        )
        return (try? fetch(descriptor)) ?? []
    }
}

//
//  DebugSeed.swift
//  Replog
//
//  DEBUG-only helpers to launch straight into a populated app for visual checks.
//  Driven by launch environment variables (never used in Release):
//    REPLOG_SEED=1     -> seed a demo plan + history and mark onboarding done
//    REPLOG_TAB=<name> -> initial tab (today|plans|library|progress|profile)
//

import Foundation
import SwiftData

#if DEBUG
@MainActor
enum DebugSeed {
    static var isSeedRequested: Bool {
        ProcessInfo.processInfo.environment["REPLOG_SEED"] == "1"
    }

    static var initialTab: MainTabView.Tab? {
        switch ProcessInfo.processInfo.environment["REPLOG_TAB"] {
        case "plans": return .plans
        case "library": return .library
        case "progress": return .progress
        case "profile": return .profile
        case "today": return .today
        default: return nil
        }
    }

    /// Seeds a demo plan + a little history if the store is empty.
    static func seedIfNeeded(_ context: ModelContext) {
        guard isSeedRequested else { return }
        let profile = context.userProfile()
        if ProcessInfo.processInfo.environment["REPLOG_DARK"] == "1" {
            context.appSettings().darkMode = true
            try? context.save()
        }
        guard !profile.onboardingDone else { return }

        var answers = QuizAnswers()
        answers.firstName = "Alex"
        answers.daysPerWeek = 3
        let generated = PlanGenerator().generate(answers)
        let report = ReportComposer.fallbackMarkdown(answers: answers, plan: generated)
        let plan = PlanFactory.insert(generated, into: context, order: 0, reportMarkdown: report)

        // Fabricate a few weeks of history for the first exercise to populate Progress.
        if let firstItem = plan.orderedWorkouts.first?.orderedItems.first {
            let exId = firstItem.exId
            let cal = Calendar.current
            for (i, e1rm) in [92, 96, 99, 104, 110].enumerated() {
                let date = cal.date(byAdding: .day, value: -(28 - i * 7), to: Date()) ?? Date()
                let entry = HistoryEntry(exId: exId, date: date, topW: Double(70 + i * 2), topR: 8,
                                         e1rm: e1rm, sets: [RecordedSet(w: Double(70 + i * 2), r: 8),
                                                            RecordedSet(w: 60, r: 10)])
                context.insert(entry)
            }
        }

        profile.name = "Alex"
        profile.streak = 3
        profile.weekStreak = 2
        profile.totalWorkouts = 12
        profile.doneDates = StreakCalendar.recordingCompletion(Date(), into: [])
        profile.onboardingDone = true
        try? context.save()

        // Optionally drop straight into a live workout for verification.
        if ProcessInfo.processInfo.environment["REPLOG_ACTIVE"] == "1",
           let workout = plan.orderedWorkouts.first {
            let session = SessionBuilder.start(workout: workout, into: context)
            if ProcessInfo.processInfo.environment["REPLOG_COMPLETE"] == "1" {
                // Mark everything done to preview the completion celebration.
                session.exercises.forEach { $0.sets.forEach { $0.done = true } }
            } else if let firstSet = session.orderedExercises.first?.orderedSets.first {
                // Mark the first exercise's first set done so the "crossing" state is visible.
                firstSet.done = true
            }
            try? context.save()
        }
    }
}
#endif

